// Targets naming this crate (ignored) and a crate that merely shares the prefix (kept).
const OWN_MODULE: &str = "grow_signoz::core";
const OWN_CRATE: &str = "grow_signoz";
const SIMILAR: &str = "grow_signoz_extra";

#[tokio::test]
async fn log_records_become_records() {
    let exp = MemoryLogExporter::new();
    let client = Arc::new(exp.client(Default::default()).unwrap());
    let bridge = LogBridge::new(client.clone()).with_max_level(log::LevelFilter::Trace);
    assert!(format!("{bridge:?}").contains("Trace"));
    bridge.init().unwrap();
    log::trace!("t");
    log::debug!("d");
    log::info!(user = "ada", n = 2, ok = true, ratio = 1.5, other:? = ("x",); "hello {}", 1);
    log::warn!("w");
    log::error!("e");
    log::info!(target: OWN_MODULE, "own crate is ignored");
    log::info!(target: OWN_CRATE, "own crate root is ignored");
    log::info!(target: SIMILAR, "similar prefix is kept");
    log::logger().flush();
    client.flush(None).await.unwrap();
    let got = exp.records();
    let bodies: Vec<&str> = got.iter().map(|r| r.body.as_str()).collect();
    assert_eq!(
        bodies,
        ["t", "d", "hello 1", "w", "e", "similar prefix is kept"]
    );
    let sev: Vec<Severity> = got.iter().take(5).map(|r| r.severity).collect();
    assert_eq!(
        sev,
        [
            Severity::Trace,
            Severity::Debug,
            Severity::Info,
            Severity::Warn,
            Severity::Error
        ]
    );
    let hello = &got[2];
    assert_eq!(hello.attributes["user"], "ada");
    assert_eq!(hello.attributes["n"], 2);
    assert_eq!(hello.attributes["ok"], true);
    assert_eq!(hello.attributes["ratio"], 1.5);
    assert_eq!(hello.attributes["other"], "(\"x\",)");
    assert_eq!(hello.attributes["log.target"], "logging_adapters");
    assert!(hello.attributes.contains_key("code.lineno"));
    // A second init fails: only one global logger.
    assert!(LogBridge::new(client.clone()).init().is_err());
}
